import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';

import { Button, Select, Typography } from 'antd';
import cn from 'classnames';

import PlusIcon from 'assets/images/icons/plus.svg?react';
import { EFilters } from 'features/Filters/model/enums';
import { useMedia } from 'shared/hooks';
import { EGaCategories, EGaEvents, EMainRoutes } from 'shared/typings';

import { OPTIONS_MAX_HEIGHT_SOURCE } from '../../consts';
import { useFilters } from '../../hooks/useFilters';
import { useSourceSelect } from '../../hooks/useSourceSelect';

import styles from './SourceFilter.module.scss';

interface ISourceFilterProps extends HTMLAttributes<HTMLDivElement> {}

export const SourceFilter: FC<ISourceFilterProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const isDesktop = useMedia('desktop');
	const navigate = useNavigate();
	const { getALLFilterValues, onFilterChange } = useFilters();
	const { sourceOptions } = useSourceSelect();

	return (
		<div {...props} className={cn(className, styles.sourceFilter)}>
			{isDesktop && <Typography.Text>{t('Specify sources')}:</Typography.Text>}
			{sourceOptions.length === 0 && (
				<Button
					icon={<PlusIcon />}
					className={cn(styles.select, styles.addSource)}
					size="large"
					type="primary"
					onClick={() => navigate(`/${EMainRoutes.SOURCES}/${EMainRoutes.CREATE}`)}>
					<Typography.Text>{t('Add a source')}</Typography.Text>
				</Button>
			)}
			{!!sourceOptions.length && (
				<Select
					value={getALLFilterValues(EFilters.SOURCE)}
					options={sourceOptions}
					onChange={(value) =>
						onFilterChange(EFilters.SOURCE, Array.isArray(value) ? value : [value], {
							event: EGaEvents.CLICK_SPECIFY_SOURCES,
							option1: EGaCategories.CATALOG,
						})
					}
					size="large"
					className={styles.select}
					listHeight={OPTIONS_MAX_HEIGHT_SOURCE}
				/>
			)}
		</div>
	);
};
